<?php declare(strict_types=1); namespace Database\Schema; use Core\Database\Schema\Blueprint; use Core\Database\Schema\SchemaDefinition; class CategoryTranslationsSchema extends SchemaDefinition { protected string $table = 'category_translations'; public function define(Blueprint $table): void { $table->id(); $table->foreignId('category_id'); $table->string_50('locale')->index(); $table->string_255('name'); $table->long_text('description')->nullable(); $table->foreign('category_id')->references('id')->on('categories')->onDelete('CASCADE'); $table->unique('category_id', 'locale'); } } 